contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(c.balances(address(this)) >= collectAmount);

        uint initialBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        c.Collect(collectAmount); if (__ESBMC_reverted()) return;

        uint finalBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(finalBalance == initialBalance + depositAmount - collectAmount);
    }

    receive() external payable {}
}

